use vstd::prelude::*;

verus! {

    // Specification for membership in Set A
    spec fn is_setA(c: char) -> bool {
        c == 'A' ||
        c == 'E' ||
        c == 'F' ||
        c == 'H' ||
        c == 'I' ||
        c == 'K' ||
        c == 'L' ||
        c == 'M' ||
        c == 'N' ||
        c == 'T' ||
        c == 'V' ||
        c == 'W' ||
        c == 'X' ||
        c == 'Y' ||
        c == 'Z'
    }

    // Specification for membership in Set B
    spec fn is_setB(c: char) -> bool {
        c == 'B' ||
        c == 'C' ||
        c == 'D' ||
        c == 'G' ||
        c == 'J' ||
        c == 'O' ||
        c == 'P' ||
        c == 'Q' ||
        c == 'R' ||
        c == 'S' ||
        c == 'U'
    }

    // solve: returns "YES" (as Vec<char>) iff all letters of `word` lie entirely
    // in Set A or entirely in Set B; otherwise returns "NO".
    fn solve(word: Vec<char>) -> (result: Vec<char>)
        requires
            // word length between 1 and 10
            1 <= word.len() && word.len() <= 10,
            // every character is in one of the two sets
            forall |i: usize| i < word.len() ==> is_setA(word[i]) || is_setB(word[i]),
        ensures
            // "YES" exactly when all in A or all in B
            (result == vec!['Y','E','S'])
              <==> (
                forall |i: usize| i < word.len() ==> is_setA(word[i])
                ||
                forall |i: usize| i < word.len() ==> is_setB(word[i])
              ),
            // "NO" exactly when not all in a single set
            (result == vec!['N','O'])
              <==> !(
                forall |i: usize| i < word.len() ==> is_setA(word[i])
                ||
                forall |i: usize| i < word.len() ==> is_setB(word[i])
              ),
    {
        let n = word.len();
        let mut i: usize = 0;
        // allA = true means "so far, every seen character is in A"
        let mut allA: bool = true;
        // allB = true means "so far, every seen character is in B"
        let mut allB: bool = true;

        // Scan the word
        while i < n
            invariant
                i <= n,
                allA ==> forall |j: usize| j < i ==> is_setA(word[j]),
                allB ==> forall |j: usize| j < i ==> is_setB(word[j]),
            decreases n - i,
        {
            let c = word[i];
            // If c is not in A, then we can no longer have "all in A"
            if !is_setA(c) {
                allA = false;
            }
            // If c is not in B, then we can no longer have "all in B"
            if !is_setB(c) {
                allB = false;
            }
            i += 1;
        }

        // At loop exit, i == n, so allA/allB exactly characterize the whole word
        assert(allA == forall |j: usize| j < n ==> is_setA(word[j]));
        assert(allB == forall |j: usize| j < n ==> is_setB(word[j]));

        if allA || allB {
            result = vec!['Y','E','S'];
        } else {
            result = vec!['N','O'];
        }
    }

} // end verus

